import unittest
from solution import to_snake_case, to_camel_case

class TestCaseConverter(unittest.TestCase):
    def test_snake_case_acronyms(self):
        self.assertEqual(to_snake_case("parseHTTPRequest"), "parse_http_request")
        self.assertEqual(to_snake_case("simpleCamelCase"), "simple_camel_case")
        self.assertEqual(to_snake_case("kebab-case-string"), "kebab_case_string")

    def test_camel_case(self):
        self.assertEqual(to_camel_case("user_id"), "userId")
        self.assertEqual(to_camel_case("get_xml_rpc_data"), "getXmlRpcData")
        self.assertEqual(to_camel_case("kebab-case-example"), "kebabCaseExample")

if __name__ == '__main__':
    unittest.main()
